referenceSolutions.javascript:
export function characterReplacement(text        , k        )         {
const counts         =Array(26).fill(0);let left=0,largest=0,best=0;for(let right=0;right<text.length;right++){const c=text.charCodeAt(right)-65;largest=Math.max(largest,++counts[c]);while(right-left+1-largest>k)counts[text.charCodeAt(left++)-65]--;best=Math.max(best,right-left+1);}return best;
}

